        <p class="error-message" id="full-name-error" hidden></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address <span class="required-indicator">*</span></label>
        <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required>
        <p class="error-message" id="email-address-error" hidden></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+1 555 123 4567">
        <p class="helper-text" id="phone-number-helper">Optional. Use numbers with spaces, dashes, or a leading +, for example +1 555 123 4567.</p>
        <p class="error-message" id="phone-number-error" hidden></p>
      </div>

      <div class="actions">
        <button type="submit">Submit request</button>
      </div>

      <p class="success-message" id="form-success" hidden>
        Thanks. Your support request is ready to send.
      </p>
    </form>
  </main>

  <script>
    const form = document.querySelector('#support-form');
    const fields = {
      fullName: {
        input: document.querySelector('#full-name'),
