 <body>
   <main class="support-shell">
     <p class="eyebrow">Support</p>
     <h1>Contact our support team</h1>
     <p class="intro">
       Send us your details and we will follow up as soon as possible to help resolve your issue.
     </p>

     <form id="support-form" novalidate>
       <div class="form-field">
         <label for="full-name">Full name <span class="required-indicator">*</span></label>
         <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required>
         <p class="error-message" id="full-name-error" hidden></p>
       </div>

       <div class="form-field">
         <label for="email-address">Email address <span class="required-indicator">*</span></label>
         <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required>
         <p class="error-message" id="email-address-error" hidden></p>
       </div>

       <div class="form-field">
         <label for="phone-number">Phone number</label>
         <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+1 555 123 4567">
         <p class="helper-text" id="phone-number-helper">Optional. Use numbers with spaces, dashes, or a leading +, for example +1 555 123 4567.</p>
         <p class="error-message" id="phone-number-error" hidden></p>
       </div>

       <div class="actions">
         <button type="submit">Submit request</button>
       </div>

       <p class="success-message" id="form-success" hidden>
         Thanks. Your support request is ready to send.
       </p>
     </form>
   </main>

   <script>
     const form = document.querySelector('#support-form');
     const fields = {
       fullName: {
         input: document.querySelector('#full-name'),
         error: document.querySelector('#full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Please enter your full name.';
           }
           return '';
         }
       },
       email: {
         input: document.querySelector('#email-address'),
         error: document.querySelector('#email-address-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Please enter your email address.';
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return 'Please enter a valid email address.';
           }

           return '';
         }
       },
       phone: {
         input: document.querySelector('#phone-number'),
         error: document.querySelector('#phone-number-error'),
         validate(value) {
           const trimmedValue = value.trim();

           if (!trimmedValue) {
             return '';
           }

           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return 'Use a valid phone number format such as +1 555 123 4567.';
           }

           return '';
         }
       }
     };

     const showFieldState = (field, message) => {
       field.error.textContent = message;
       field.error.hidden = !message;
       field.input.classList.toggle('input-error', Boolean(message));
       field.input.setAttribute('aria-invalid', String(Boolean(message)));
     };

     const validateField = (field) => {
       const message = field.validate(field.input.value);
       showFieldState(field, message);
       return !message;
     };

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (!field.error.hidden) {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const allValid = Object.values(fields).every((field) => validateField(field));
       const successMessage = document.querySelector('#form-success');

       if (!allValid) {
         successMessage.hidden = true;
         return;
       }

       successMessage.hidden = false;
       form.reset();
       Object.values(fields).forEach((field) => showFieldState(field, ''));
     });
   </script>
